import{_ as t,o as d,c as s,ag as o}from"./chunks/framework.BZohXCq9.js";const b=JSON.parse('{"title":"Student Dashboard -> Overview Analytics (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/student-dashboard/overview-analytics.md","filePath":"modules/student-dashboard/overview-analytics.md"}'),a={name:"modules/student-dashboard/overview-analytics.md"};function r(l,e,n,i,c,u){return d(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="student-dashboard-overview-analytics-deep" tabindex="-1">Student Dashboard -&gt; Overview Analytics (deep) <a class="header-anchor" href="#student-dashboard-overview-analytics-deep" aria-label="Permalink to &quot;Student Dashboard -&gt; Overview Analytics (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>student-dashboard</code><br><strong>Feature:</strong> <code>overview-analytics</code><br><strong>Route:</strong> <code>/student-dashboard/overview</code></p><p>This screen is the student home dashboard. It summarizes the student’s learning state through stat cards, shows recent/weekly lesson entries, and surfaces notes/feedback left by instructors.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Show high-level student metrics: total lessons, current bookings, total instructors, remaining hours, and related booking counts.</li><li>Show lesson history in a compact dashboard format so the student can quickly understand what is booked/completed/in progress.</li><li>Surface instructor feedback/notes in a modal-style interaction without forcing the student into the dedicated feedback/rating pages.</li><li>Provide a shortcut CTA to instructor discovery via “Find Instructor”.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/student-dashboard/studentOverview.tsx</code></td><td>Main overview page</td><td>Calls dashboard stats, lesson list, and feedback queries; composes stat cards, table-like lesson list, CTA, and feedback modal flow.</td></tr><tr><td><code>Frontend/src/components/StudentComponents/StudentDashboard/LoadingCard.tsx</code></td><td>Loading placeholder card</td><td>Used while dashboard stat blocks are loading.</td></tr><tr><td><code>Frontend/src/components/StudentComponents/StudentDashboard/CircularProgressDashboard.tsx</code></td><td>Circular progress card UI</td><td>Used for dashboard metric visualisation where applicable.</td></tr><tr><td><code>Frontend/src/components/StudentComponents/StudentDashboard/FeedBackModal.tsx</code></td><td>Feedback detail modal</td><td>Renders instructor note/feedback details selected from the overview.</td></tr><tr><td><code>Frontend/src/context/AuthContext.tsx</code></td><td>Auth state</td><td>Supplies current student id for query variables.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="get-student-dashboard-stats" tabindex="-1"><code>GET_STUDENT_DASHBOARD_STATS</code> <a class="header-anchor" href="#get-student-dashboard-stats" aria-label="Permalink to &quot;`GET_STUDENT_DASHBOARD_STATS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/StudentDashboard.ts</code></li><li>Query field: <code>getStudentDashboardStats(studentId: ID!)</code></li><li>Returns: <ul><li><code>totalLessons</code></li><li><code>bookedLessons</code></li><li><code>cancelledLessons</code></li><li><code>semiCancelledLessons</code></li><li><code>currentBookings</code></li><li><code>totalInstructors</code></li><li><code>remainingHours</code></li></ul></li><li>Used by: <code>studentOverview.tsx</code> stat cards.</li></ul><h3 id="get-student-lessons" tabindex="-1"><code>GET_STUDENT_LESSONS</code> <a class="header-anchor" href="#get-student-lessons" aria-label="Permalink to &quot;`GET_STUDENT_LESSONS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/StudentDashboard.ts</code></li><li>Query field: <code>getStudentLesson(studentId: ID!)</code></li><li>Returns lesson rows with: <ul><li><code>lessonId</code></li><li><code>instructorId</code></li><li><code>instructorName</code></li><li><code>date</code></li><li><code>startTime</code></li><li><code>endTime</code></li><li><code>slotStatus</code></li><li><code>isCompleted</code></li><li><code>isReviewed</code></li></ul></li><li>Used by: the weekly lessons/history section.</li></ul><h3 id="get-student-feedbacks" tabindex="-1"><code>GET_STUDENT_FEEDBACKS</code> <a class="header-anchor" href="#get-student-feedbacks" aria-label="Permalink to &quot;`GET_STUDENT_FEEDBACKS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/Queries/StudentDashboard.ts</code></li><li>Query field: <code>getStudentFeedbacks(studentId: ID!)</code></li><li>Returns instructor feedback metadata and message content.</li><li>Used by: instructor-notes area and <code>FeedBackModal</code>.</li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs/studentDashboard.js</code></li><li>Relevant query fields: <ul><li><code>getStudentDashboardStats(studentId: ID!): StudentDashboardStats</code></li><li><code>getStudentLesson(studentId: ID!): [StudentLesson!]!</code></li><li><code>getStudentFeedbacks(studentId: ID!): [LessonFeedback!]!</code></li></ul></li><li>Related types: <ul><li>dashboard stats shape</li><li>lesson summary shape</li><li>feedback objects reused from lesson-feedback area</li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers/studentDashboard.resolver.js</code></li><li>Relevant resolvers: <ul><li><code>Query.getStudentDashboardStats</code><ul><li>Aggregates lesson counts and current booking-related numbers for a student.</li></ul></li><li><code>Query.getStudentLesson</code><ul><li>Reads booking/slot data and returns lesson-level rows for the dashboard lesson list.</li></ul></li><li><code>Query.getStudentFeedbacks</code><ul><li>Returns instructor-written feedback connected to the student.</li></ul></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/studentBooking.model.js</code></td><td>Main booking + slot source for lesson counts and lesson list rows</td></tr><tr><td><code>server/src/models/User.js</code></td><td>Student identity and remaining-hours related fields</td></tr><tr><td><code>server/src/models/LessonFeedBack.js</code></td><td>Instructor-to-student lesson feedback records</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Student opens <code>/student-dashboard/overview</code>.</li><li><code>studentOverview.tsx</code> reads the current student id from <code>AuthContext</code>.</li><li>The page sends three independent GraphQL queries: <ul><li>stats</li><li>lessons</li><li>feedbacks</li></ul></li><li>The backend resolver layer reads bookings, student fields, and lesson feedback documents.</li><li>The page renders top-level summary cards and lesson entries.</li><li>If the student opens an instructor note, the feedback modal renders the selected feedback document returned from <code>getStudentFeedbacks</code>.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>This page is read-heavy and intentionally uses separate queries instead of one large payload, which lets the UI show partial success/error states.</li><li>The weekly/lesson-history section is shaped from booking slot data, not from a separate analytics table.</li><li>Feedback shown here is read-only; creation/edit flows live in the feedback/rating module docs.</li></ul>',25)])])}const p=t(a,[["render",r]]);export{b as __pageData,p as default};
